argv:
$ErrorActionPreference='Stop'
Add-Type -AssemblyName UIAutomationClient
Add-Type -AssemblyName UIAutomationTypes
$edge=Get-Process msedge -ErrorAction SilentlyContinue | Where-Object {$_.MainWindowHandle -ne 0} | Select-Object -First 1
if($null -eq $edge){throw 'No visible Edge window'}
$root=[System.Windows.Automation.AutomationElement]::FromHandle($edge.MainWindowHandle)
$all=$root.FindAll([System.Windows.Automation.TreeScope]::Descendants,[System.Windows.Automation.Condition]::TrueCondition)
$target=[Text.Encoding]::UTF8.GetString([Convert]::FromBase64String('5paH5a2X5qyE5L2N56m655m944CC6KuL6Ly45YWl5YWn5a655Lul5pKw5a+r5paw6LK85paH44CC'))
$btn=$null
for($i=0;$i -lt $all.Count;$i++){
 $e=$all.Item($i)
 if($e.Current.ControlType -eq [System.Windows.Automation.ControlType]::Button -and [string]$e.Current.Name -eq $target){$btn=$e;break}
}
if($null -eq $btn){throw 'Threads composer entry not found'}
$invoke=$btn.GetCurrentPattern([System.Windows.Automation.InvokePattern]::Pattern)
$invoke.Invoke()
Start-Sleep -Seconds 2
$root=[System.Windows.Automation.AutomationElement]::FromHandle($edge.MainWindowHandle)
$all=$root.FindAll([System.Windows.Automation.TreeScope]::Descendants,[System.Windows.Automation.Condition]::TrueCondition)
$out=@()
for($i=0;$i -lt $all.Count;$i++){
 $e=$all.Item($i)
 $ct=$e.Current.ControlType.ProgrammaticName
 $name=[string]$e.Current.Name
 if(($ct -match 'Button|Edit|Text|Hyperlink|Pane') -and $name){
   $r=$e.Current.BoundingRectangle
   $out += [pscustomobject]@{type=$ct;name=$name;aid=[string]$e.Current.AutomationId;x=[string]$r.X;y=[string]$r.Y;w=[string]$r.Width;h=[string]$r.Height;enabled=[bool]$e.Current.IsEnabled;focus=[bool]$e.Current.HasKeyboardFocus}
   if($out.Count -ge 200){break}
 }
}
[pscustomobject]@{title=$edge.MainWindowTitle;controls=$out}|ConvertTo-Json -Depth 6 -Compress
